27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 format")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    public String getCustomerCode() {
61	        return this.customerCode;
62	    }
63	
64	    public void setCustomerCode(String customerCode) {
65	        this.customerCode = customerCode;
66	    }
67	
68	    /** Assign the customer code '<LAST3>-<NNNN>' for the given global owner sequence number. */
69	    public void assignCustomerCode(int sequence) {
70	        this.customerCode = getLastName().substring(0, 3).toUpperCase() + String.format("-%04d", sequence);
71	    }
72	
73	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
74	    private Set<Pet> pets;
75	
76	    public String getEmail() {
77	        return this.email;
78	    }
79	
80	    /** Store the email lower-cased so it is persisted and returned normalised. */
81	    public void setEmail(String email) {
82	        this.email = (email == null) ? null : email.toLowerCase();
83	    }
84	
85	    public LocalDate getRegistrationDate() {
86	        return this.registrationDate;
87	    }
88	
89	    public void setRegistrationDate(LocalDate registrationDate) {
90	        this.registrationDate = registrationDate;
91	    }
92	
93	    /** Default a missing registration date to the server's current date on create. */
94	    @PrePersist
95	    protected void ensureRegistrationDate() {
96	        if (this.registrationDate == null) {
97	            this.registrationDate = LocalDate.now();
98	        }
99	    }
100	
101	    public String getAddress() {
102	        return this.address;
103	    }
104	
105	    public void setAddress(String address) {
106	        this.address = address;
107	    }
108	
109	    public String getCity() {
110	        return this.city;
111	    }
112	
113	    public void setCity(String city) {
114	        this.city = city;
115	    }
116	
117	    public String getTelephone() {
118	        return this.telephone;
119	    }
120	
121	    public void setTelephone(String telephone) {
122	        this.telephone = telephone;
123	    }
124	
125	    protected Set<Pet> getPetsInternal() {
126	        if (this.pets == null) {
127	            this.pets = new HashSet<>();
128	        }
129	        return this.pets;
130	    }
131	
132	    protected void setPetsInternal(Set<Pet> pets) {
133	        this.pets = pets;
134	    }
135	
136	    public List<Pet> getPets() {
137	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
138	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
139	        return Collections.unmodifiableList(sortedPets);
140	    }
141	
142	    public void setPets(List<Pet> pets) {
143	        this.pets = new HashSet<>(pets);
144	    }
145	
146	    public void addPet(Pet pet) {
147	        getPetsInternal().add(pet);
148	        pet.setOwner(this);
149	    }
150	
151	    /**
152	     * Return the Pet with the given name, or null if none found for this Owner.
153	     *
154	     * @param name to test
155	     * @return true if pet name is already in use
156	     */
157	    public Pet getPet(String name) {
158	        return getPet(name, false);
159	    }
160	
161	    /**
162	     * Return the Pet with the given name, or null if none found for this Owner.
163	     *
164	     * @param name to test
165	     * @return true if pet name is already in use
166	     */
167	    public Pet getPet(String name, boolean ignoreNew) {
168	        name = name.toLowerCase();
169	        for (Pet pet : getPetsInternal()) {
170	            if (!ignoreNew || !pet.isNew()) {
171	                String compName = pet.getName();
172	                compName = compName.toLowerCase();
173	                if (compName.equals(name)) {
174	                    return pet;
175	                }
176	            }
177	        }
178	        return null;
179	    }
180	
181	    public Pet getPet(Integer petId) {
182	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
183	    }
184	
185	    @Override
186	    public String toString() {
187	        return new ToStringCreator(this)
188	
189	            .append("id", this.getId())
190	            .append("new", this.isNew())
191	            .append("lastName", this.getLastName())
192	            .append("firstName", this.getFirstName())
193	            .append("address", this.address)
194	            .append("city", this.city)
195	            .append("telephone", this.telephone)
196	            .toString();
197	    }
198	}
