5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Detects owners that share a household, i.e. carry the same last name and the
9	 * same address compared case-insensitively with collapsed whitespace.
10	 */
11	final class Households {
12	
13	    private Households() {
14	    }
15	
16	    /** Trim, collapse internal whitespace and lower-case a value for comparison. */
17	    private static String normalize(String value) {
18	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
19	    }
20	
21	    /** True when an existing owner has the candidate's last name and address. */
22	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
23	        String lastName = normalize(candidate.getLastName());
24	        String address = normalize(candidate.getAddress());
25	        return existing.stream().anyMatch(o ->
26	            normalize(o.getLastName()).equals(lastName) && normalize(o.getAddress()).equals(address));
27	    }
28	}
